?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financial Reconciliation | SMM Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="/admin/">Financials</a><a class="btn btn-outline-light btn-sm" href="/admin/operations.php">Operations</a></div></nav><main class="container-fluid py-4"><div class="d-flex justify-content-between align-items-center mb-3"><h2>Financial Reconciliation</h2><form><select name="days" class="form-select" onchange="this.form.submit()"><option value="1" <?=$days===1?'selected':''?>>24 hours</option><option value="7" <?=$days===7?'selected':''?>>7 days</option><option value="30" <?=$days===30?'selected':''?>>30 days</option><option value="90" <?=$days===90?'selected':''?>>90 days</option></select></form></div><div class="alert alert-<?=$balanced?'success':'danger'?>"><?=$balanced?'✓ Financial ledgers reconcile for the selected period.':'⚠ Reconciliation differences detected. Investigate the exceptions below.'?></div><div class="row g-3 mb-4"><div class="col-md-3"><div class="card"><div class="card-body"><small>Paid payments</small><h3>₦<?=number_format($summary['paid_payments'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Completed deposits</small><h3>₦<?=number_format($summary['completed_deposits'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Ledger net</small><h3>₦<?=number_format($summary['ledger_net'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Customer balances</small><h3>₦<?=number_format($summary['customer_wallet_balance'],2)?></h3></div></div></div></div><div class="card"><div class="card-header">Exceptions: paid payments without wallet transaction</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Payment</th><th>User</th><th>Amount</th><th>Paid</th><th>Status</th></tr></thead><tbody><?php foreach($exceptions as $e):?><tr><td><code><?=htmlspecialchars($e['reference'])?></code></td><td><?=htmlspecialchars((string)$e['user_id'])?></td><td>₦<?=number_format((float)$e['amount'],2)?></td><td><?=htmlspecialchars((string)$e['paid_at'])?></td><td><span class="badge text-bg-danger">Missing transaction</span></td></tr><?php endforeach;if(!$exceptions):?><tr><td colspan="5" class="text-center text-muted py-4">No exceptions found.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>
